    inline bool Readable(const void* address, size_t size)
    {
        auto current = reinterpret_cast<uintptr_t>(address);
        if (!current || size > UINTPTR_MAX - current) return false;
        auto end = current + size;
        while (current < end)
        {
            MEMORY_BASIC_INFORMATION region{};
            if (!VirtualQuery(reinterpret_cast<void*>(current), &region, sizeof(region))
                || region.State != MEM_COMMIT || (region.Protect & (PAGE_GUARD | PAGE_NOACCESS))) return false;
            auto next = reinterpret_cast<uintptr_t>(region.BaseAddress) + region.RegionSize;
            if (next <= current) return false;
            current = next;
        }
        return true;
    }

    template<size_t Count> bool Matches(HMODULE module, const Prefix (&prefixes)[Count], uint32_t minimumSize,
        uintptr_t relocatedPreferred = 0)
    {
        if (!module || !Readable(module, sizeof(IMAGE_DOS_HEADER))) return false;
        auto base = reinterpret_cast<uintptr_t>(module);
        auto dos = reinterpret_cast<const IMAGE_DOS_HEADER*>(module);
        if (dos->e_magic != IMAGE_DOS_SIGNATURE || dos->e_lfanew < 0 || dos->e_lfanew > 0x100000) return false;
        auto nt = reinterpret_cast<const IMAGE_NT_HEADERS32*>(base + dos->e_lfanew);
        if (!Readable(nt, sizeof(*nt)) || nt->Signature != IMAGE_NT_SIGNATURE
            || nt->FileHeader.Machine != IMAGE_FILE_MACHINE_I386
            || nt->OptionalHeader.Magic != IMAGE_NT_OPTIONAL_HDR32_MAGIC
            || nt->OptionalHeader.SizeOfImage < minimumSize) return false;
        // Undo only HIGHLOW fixups explicitly listed by this PE. Every contract
        // byte still compares exactly; relocated operands are never wildcards.
        std::vector<uint32_t> fixups;
        const auto delta = static_cast<uint32_t>(base - relocatedPreferred);
        if (relocatedPreferred && delta)
        {
            if (nt->OptionalHeader.ImageBase != relocatedPreferred
                || nt->OptionalHeader.SizeOfImage != 0xFE000) return false;
            const auto& directory = nt->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_BASERELOC];
            if (!directory.VirtualAddress || directory.Size < sizeof(IMAGE_BASE_RELOCATION)
                || directory.VirtualAddress > nt->OptionalHeader.SizeOfImage
                || directory.Size > nt->OptionalHeader.SizeOfImage - directory.VirtualAddress
                || !Readable(reinterpret_cast<void*>(base + directory.VirtualAddress), directory.Size)) return false;
            uint32_t offset = 0;
            while (offset < directory.Size)
            {
                if (directory.Size - offset < sizeof(IMAGE_BASE_RELOCATION)) return false;
                auto block = reinterpret_cast<const IMAGE_BASE_RELOCATION*>(base + directory.VirtualAddress + offset);
                if (block->SizeOfBlock < sizeof(*block) || block->SizeOfBlock > directory.Size - offset
                    || (block->SizeOfBlock - sizeof(*block)) % sizeof(uint16_t)) return false;
                auto entries = reinterpret_cast<const uint16_t*>(block + 1);
                for (size_t i = 0; i < (block->SizeOfBlock - sizeof(*block)) / sizeof(uint16_t); ++i)
                {
                    const auto type = entries[i] >> 12;
                    if (type == IMAGE_REL_BASED_ABSOLUTE) continue;
                    if (type != IMAGE_REL_BASED_HIGHLOW || block->VirtualAddress > nt->OptionalHeader.SizeOfImage - 4
                        || static_cast<uint32_t>(entries[i] & 0xFFF) > nt->OptionalHeader.SizeOfImage - 4 - block->VirtualAddress) return false;
                    fixups.push_back(block->VirtualAddress + (entries[i] & 0xFFF));
                }
                offset += block->SizeOfBlock;
            }
            std::sort(fixups.begin(), fixups.end());
            if (std::adjacent_find(fixups.begin(), fixups.end()) != fixups.end()) return false;
        }
        for (const auto& prefix : prefixes)
        {
            if (prefix.rva > nt->OptionalHeader.SizeOfImage - sizeof(prefix.bytes)
                || !Readable(reinterpret_cast<void*>(base + prefix.rva), sizeof(prefix.bytes))) return false;
            uint8_t actual[sizeof(prefix.bytes)];
            std::memcpy(actual, reinterpret_cast<void*>(base + prefix.rva), sizeof(actual));
            for (auto it = std::lower_bound(fixups.begin(), fixups.end(), prefix.rva > 3 ? prefix.rva - 3 : 0);
                it != fixups.end() && *it < prefix.rva + sizeof(actual); ++it)
            {
                if (!Readable(reinterpret_cast<void*>(base + *it), sizeof(uint32_t))) return false;
                uint32_t normalized;
                std::memcpy(&normalized, reinterpret_cast<void*>(base + *it), sizeof(normalized));
                normalized -= delta;
                for (size_t byte = 0; byte < sizeof(normalized); ++byte)
                    if (*it + byte >= prefix.rva && *it + byte < prefix.rva + sizeof(actual))
                        actual[*it + byte - prefix.rva] = reinterpret_cast<const uint8_t*>(&normalized)[byte];
            }
            if (std::memcmp(actual, prefix.bytes, sizeof(actual))) return false;
        }
        return true;
    }
